@@ -436,29 +435,16 @@ function announceThread(deps: ActionDependencies, thread: Thread): void {
 	log.endGroup();
 }

-/**
- * After the final push: where the thread is now, in the log. How to read it goes in the job summary in `output` mode;
- * in `comment` mode, each comment has it, collapsed (#80).
- */
-async function showThread(
+/** After the final push: where the thread is now, in the log. Each comment says how to read it (#80). */
+function showThread(
 	deps: ActionDependencies,
 	thread: Thread,
 	ref: string,
-): Promise<void> {
-	const { log } = deps;
-	const remote = deps.remote ?? "origin";
+): void {
 	const { tip } = thread;
-	log.info(
+	deps.log.info(
 		`🧵 ${ref} is at ${tip === undefined ? "(nothing stored)" : tip.slice(0, 7)}`,
 	);
-	if (deps.inputs.outputMode !== "output") {
-		return;
-	}
-	try {
-		await deps.summary?.(formatThreadSummary(ref, remote));
-	} catch (error) {
-		log.warning(`Could not write the job summary: ${getErrorMessage(error)}`);
-	}
 }

